<script setup lang="ts">
import {cloudCommunity,saveCloudPost,syncCommunity} from '../services/remoteCommunity'
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {onBeforeRouteLeave} from 'vue-router'
import {showToast,showConfirmDialog} from 'vant'
import {store,currentPets,image,compressImage} from '../stores/community'
import {postKinds,kindOf,validatePost} from '../services/community'
import type {Post} from '../types'
const router=useRouter(),route=useRoute(),title=ref(''),content=ref(''),kind=ref<Post['kind']>('chat'),role=ref<'find'|'offer'>('find'),serviceKind=ref('代遛'),location=ref(''),when=ref(''),price=ref(''),petIds=ref<string[]>([]),photos=ref<string[]>([]),busy=ref(false),uploading=ref(false),editing=ref(''),saved=ref(false),baseline=ref('')
const snapshot=()=>JSON.stringify([title.value,content.value,kind.value,role.value,location.value,when.value,price.value,serviceKind.value,petIds.value,photos.value])
watch(()=>route.fullPath,()=>{const p=store.posts.find(p=>p.id===route.query.edit&&p.mine);editing.value=p?.id||'';kind.value=p?kindOf(p):(postKinds.some(k=>k.id===route.query.kind)?route.query.kind as Post['kind']:'chat');role.value=p?.serviceRole||(route.query.role==='offer'?'offer':'find');title.value=p?.title||'';content.value=p?.content||'';location.value=p?.location||'';when.value=p?.when||'';price.value=p?.price||'';serviceKind.value=p?.serviceKind||'代遛';petIds.value=p?.petIds?.filter(id=>currentPets.value.some(p=>p.id===id))||currentPets.value.slice(0,1).map(p=>p.id);photos.value=p?.photos?.length?[...p.photos]:p?.image?[p.image]:[];baseline.value=snapshot();saved.value=false},{immediate:true})
const needsPlace=computed(()=>kind.value!=='chat')
const kindDetails={chat:{icon:'chat-o',hint:'分享养宠日常',title:'记录每一个可爱瞬间',placeholder:'今天，毛孩子又带来了什么惊喜？聊聊你们的小日常，也可以分享养宠心得…'},buddy:{icon:'friends-o',hint:'一起出门玩',title:'给快乐找个小伙伴',placeholder:'想约谁一起玩？介绍一下毛孩子的性格、活动安排和同行要求吧…'},lost:{icon:'location-o',hint:'多一份寻找的力量',title:'让更多邻居帮忙留意',placeholder:'描述宠物外貌、明显特征、最后出现的地点和时间，留下合适的联系途径…'},service:{icon:'service-o',hint:'邻里互相搭把手',title:'把需求说清楚，更好遇见彼此',placeholder:'介绍服务内容或照护需求、宠物习惯、时间安排，以及需要提前沟通的事项…'}}
const currentKind=computed(()=>kindDetails[kind.value||'chat'])
async function pick(e:Event){const input=e.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;if(files.length+photos.value.length>3){showToast('最多上传 3 张图片');input.value='';return}uploading.value=true;try{const images=await Promise.all(files.map(compressImage));photos.value.push(...images)}catch(e){showToast((e as Error).message)}finally{uploading.value=false;input.value=''}}
function togglePet(id:string){petIds.value=petIds.value.includes(id)?petIds.value.filter(x=>x!==id):[...petIds.value,id]}
async function submit(){if(busy.value)return;if(!store.profile){router.push('/auth');return}if(!currentPets.value.length){showToast('请先添加你的宠物档案');await router.push({path:'/pets',query:{add:'1',next:route.fullPath}});return}if(uploading.value){showToast('请等待图片处理完成');return}const err=validatePost({title:title.value,content:content.value,kind:kind.value||'chat',location:location.value,when:when.value,price:kind.value==='service'?price.value:''});if(err){showToast(err);return}busy.value=true;const old=store.posts.find(p=>p.id===editing.value&&p.mine);if(route.query.edit&&!old){busy.value=false;showToast('帖子加载失败或没有编辑权限，请返回社区重试');return}const now=Date.now();const post:Post={id:old?.id||crypto.randomUUID(),title:title.value.trim(),content:content.value.trim(),kind:kind.value,category:postKinds.find(k=>k.id===kind.value)!.label,serviceRole:kind.value==='service'?role.value:undefined,serviceKind:kind.value==='service'?serviceKind.value:undefined,price:kind.value==='service'?price.value:undefined,location:location.value.trim(),when:when.value.trim(),petIds:[...petIds.value],photos:[...photos.value],image:photos.value[0]||'',author:old?.author||store.profile.name,avatar:old?.avatar||currentPets.value[0]?.photo||image('pet-yunduo'),likes:old?.likes||0,liked:old?.liked||false,createdAt:old?.createdAt||now,updatedAt:now,mine:true,comments:old?.comments||[]};try{if(cloudCommunity){const id=await saveCloudPost(post,old);saved.value=true;showToast(editing.value?'云端帖子已更新':'已发布到云端');await syncCommunity().catch(()=>showToast('发布成功，列表刷新失败，请稍后重试'));await router.replace('/posts/'+id);return}if(old)store.posts.splice(store.posts.indexOf(old),1,post);else store.posts.unshift(post);saved.value=true;showToast(editing.value?'帖子已更新':'已发布到本机社区');await router.replace('/posts/'+post.id);}catch(e){showToast((e as Error).message||'发布失败，请重试')}finally{busy.value=false}}
onBeforeRouteLeave(async()=>{if(saved.value||snapshot()===baseline.value)return true;try{await showConfirmDialog({title:'离开发布页？',message:'尚未保存的内容将丢失。'});return true}catch{return false}})
</script>
<template><main class="publish-page"><header class="compose-nav"><RouterLink to="/community" aria-label="返回社区"><van-icon name="arrow-left"/></RouterLink><h1>{{editing?'编辑帖子':'发布帖子'}}</h1><span>{{editing?'修改内容':'分享美好'}}</span></header><div class="compose-intro"><span class="intro-star">✦</span><div><strong>{{currentKind.title}}</strong><p>每一份分享，都让这个小社区更温暖一点。</p></div></div>
<van-form @submit="submit"><section class="compose-card type-card"><div class="section-label"><h2>这次想分享什么？</h2><span>选择一个类型</span></div><div class="type-grid"><button v-for="k in postKinds" :key="k.id" type="button" :aria-pressed="kind===k.id" @click="kind=k.id"><span class="type-icon"><van-icon :name="kindDetails[k.id].icon"/></span><b>{{k.label}}</b><small>{{kindDetails[k.id].hint}}</small><van-icon v-if="kind===k.id" name="checked" class="type-check"/></button></div></section>
<section class="compose-card writing-card"><div class="section-label"><h2><span class="label-dot"></span>写下你的故事</h2><span>必填</span></div><van-field class="title-field" v-model="title" label="标题" placeholder="给这条帖子起个名字吧" maxlength="60" show-word-limit :rules="[{validator:v=>!!v.trim(),message:'先给帖子起个名字吧'}]"/><van-field class="body-field" v-model="content" label="内容" type="textarea" :placeholder="currentKind.placeholder" rows="5" autosize maxlength="1000" show-word-limit :rules="[{validator:v=>!!v.trim(),message:'写点内容再发布吧'}]"/><div class="photo-heading"><span><van-icon name="photo-o"/> 照片让故事更生动</span><small>{{photos.length}} / 3</small></div><div class="photo-grid"><div v-for="(src,index) in photos" :key="index" class="photo-preview"><img :src="src" :alt="'帖子图片 '+(index+1)"/><span v-if="index===0" class="cover-badge">封面</span><button type="button" :aria-label="'删除图片 '+(index+1)" @click="photos.splice(index,1)">×</button></div><label v-if="photos.length<3" class="photo-add"><van-icon :name="uploading?'clock-o':'plus'" size="24"/><span>{{uploading?'处理中…':'添加照片'}}</span><input type="file" aria-label="添加照片" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="pick"/></label></div><p class="upload-hint">选填 · 最多 3 张，单张不超过 10MB</p></section>
<section v-if="kind==='service'" class="compose-card"><div class="section-label"><h2><van-icon name="service-o"/> 服务信息</h2><span>让彼此更了解</span></div><div class="role-tabs"><button type="button" :aria-pressed="role==='find'" @click="role='find'"><van-icon name="search"/> 我需要服务</button><button type="button" :aria-pressed="role==='offer'" @click="role='offer'"><van-icon name="like-o"/> 我提供服务</button></div><label class="service-select"><span>服务类型</span><select v-model="serviceKind"><option v-for="s in ['代遛','上门喂养','宠物接送','寄养','洗护','其他']" :key="s">{{s}}</option></select></label><van-field v-model="price" label="参考费用" type="number" placeholder="留空表示待商议" maxlength="9"><template #right-icon><span class="unit">元</span></template></van-field></section>
<section class="compose-card details-card"><div class="section-label"><h2><van-icon name="location-o"/> {{kind==='lost'?'最后出现在哪里？':kind==='service'?'服务安排':'补充一点小细节'}}</h2><span>{{needsPlace?'必填':'选填'}}</span></div><van-field v-model="location" :label="kind==='lost'?'走失地点':kind==='service'?'服务地区':'活动地点'" :placeholder="needsPlace?'填写大致地区或地点':'例如：上海 · 徐汇滨江'" maxlength="60" :rules="[{validator:v=>!needsPlace||!!v.trim(),message:'请填写地点或地区'}]"/><van-field v-if="needsPlace" v-model="when" :label="kind==='lost'?'走失时间':kind==='service'?'服务时间':'活动时间'" placeholder="例如：周末下午，具体时间沟通" maxlength="60" :rules="[{validator:v=>!!v.trim(),message:'请填写时间安排'}]"/><p class="location-hint"><van-icon name="shield-o"/> 填写大致位置就好，记得保护个人隐私。</p></section>
<section v-if="!cloudCommunity" class="compose-card pet-card-section"><div class="section-label"><h2><van-icon name="smile-o"/> 谁是这次的主角？</h2><span>选填 · 可多选</span></div><div v-if="currentPets.length" class="pet-choices"><button v-for="p in currentPets" :key="p.id" type="button" :aria-pressed="petIds.includes(p.id)" @click="togglePet(p.id)"><img :src="p.photo" :alt="p.name"/><span>{{p.name}}</span><van-icon v-if="petIds.includes(p.id)" name="checked"/></button></div><div v-else class="empty-pets"><span class="empty-paw">🐾</span><div><b>为故事里的主角留个位置</b><p>请先添加宠物档案，再发布帖子。</p></div></div></section>
<p v-if="kind==='service'" class="publish-notice">服务帖子可供浏览；咨询与接单意向同步云端，未接入预约或支付。</p><p class="compose-footnote">友善分享，尊重每一位铲屎官和毛孩子。<br>{{cloudCommunity?'图文发布后保存在云端，其他登录用户可见。':'当前内容仅保存在此浏览器。'}}</p><div class="compose-action"><div class="action-context"><span class="action-icon"><van-icon :name="currentKind.icon"/></span><div><b>{{postKinds.find(k=>k.id===kind)?.label}}</b><small>{{editing?'修改后记得保存':'准备好分享你的故事了吗？'}}</small></div></div><van-button :aria-label="editing?'保存修改':'发布帖子'" round native-type="submit" :disabled="uploading" :loading="busy" color="linear-gradient(120deg,#e68068,#d0614e)">{{editing?'保存修改':'发布帖子'}} <van-icon name="arrow"/></van-button></div></van-form></main></template>
